def utcnow() -> datetime:
    return datetime.now(timezone.utc).replace(tzinfo=None, microsecond=0)


def fmt(dt: datetime) -> str:
    return dt.strftime(DATE_FMT)


def parse_dt(value: str) -> datetime:
    return datetime.strptime(value, DATE_FMT)


def _writable(path: Path) -> bool:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        probe = path.parent / ".write_probe"
        probe.write_text("ok")
        probe.unlink()
        return True
    except OSError:
        return False


def get_db_path() -> Path:
    """Resolve the SQLite path. Override with CATALOG_DB_PATH; falls back to a temp dir
    when the repository directory is read-only (e.g. some hosted environments)."""
    env = os.environ.get("CATALOG_DB_PATH")
    if env:
        return Path(env)
    default = ROOT / "data" / "catalog.db"
    if _writable(default):
        return default
    return Path(tempfile.gettempdir()) / "catalog_intel" / "catalog.db"
